TLM.f("Sancti/08-16",{"officium":"S. Joachim Confessoris, Patris B. Mariæ Virginis","rule":["ex C5;","Gloria","no Credo"],"fallback":"Commune/C5","from":{"Lectio":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 111:9"},{"k":"text","la":"Dispérsit, dedit paupéribus: justítia ejus manet in sǽculum sǽculi: cornu ejus exaltábitur in glória."},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dispérsit, dedit paupéribus: justítia ejus manet in sǽculum sǽculi: cornu ejus exaltábitur in glória."}],"Oratio":[{"k":"text","la":"Deus, qui præ ómnibus Sanctis tuis beátum Jóachim Genetrícis Fílii tui patrem esse voluísti: concéde, quǽsumus; ut, cujus festa venerámur, ejus quoque perpétuo patrocínia sentiámus."},{"k":"macro","name":"Per eumdem"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 31:8-11"},{"k":"text","la":"Beátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum."}],"Graduale":[{"k":"ref","la":"Ps 111:9; 111:2"},{"k":"text","la":"Dispérsit, dedit paupéribus: justítia ejus manet in sǽculum sǽculi."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"O Jóachim, sanctæ conjux Annæ, pater almæ Vírginis, hic fámulis ferto salútis opem. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 111:2"},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur. Allelúja."},{"k":"text","la":"O Ioachim, sanctæ conjux Annæ, pater almæ Vírginis, hic fámulis ferto salútis opem. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Initium ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 1:1-16"},{"k":"text","la":"Liber generatiónis Jesu Christi, fílii David, fílii Abraham. Abraham génuit Isaac. Isaac autem génuit Jacob. Jacob autem génuit Judam et fratres ejus. Judas autem génuit Phares et Zaram de Thamar. Phares autem génuit Esron. Esron autem génuit Aram. Aram autem génuit Amínadab. Amínadab autem génuit Naásson. Naásson autem génuit Salmon. Salmon autem génuit Booz de Rahab. Booz autem génuit Obed ex Ruth. Obed autem génuit Jesse. Jesse autem génuit David regem. David autem rex génuit Salomónem ex ea, quæ fuit Uriæ. Sálomon autem génuit Róboam. Róboam autem génuit Abíam. Abías autem génuit Asa. Asa autem génuit Jósaphat. Jósaphat autem génuit Joram. Joram autem génuit Ozíam. Ozías autem génuit Jóatham. Jóatham autem génuit Achaz. Achaz autem génuit Ezechíam. Ezechías autem génuit Manássen. Manásses autem génuit Amon. Amon autem génuit Josíam. Josías autem génuit Jechoníam et fratres ejus in transmigratióne Babylónis. Et post transmigratiónem Babylónis: Jechonías génuit Saláthiel. Saláthiel autem génuit Zoróbabel. Zoróbabel autem génuit Abiud. Abiud autem génuit Elíacim. Elíacim autem génuit Azor. Azor autem génuit Sadoc. Sadoc autem génuit Achim. Achim autem génuit Eliud. Eliud autem génuit Eleázar. Eleázar autem génuit Mathan. Mathan autem génuit Jacob. Jacob autem génuit Joseph, virum Maríæ, de qua natus est Jesus, qui vocátur Christus."}],"Offertorium":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honóre coronásti eum: et constituísti eum super ópera mánuum tuárum, Dómine."}],"Secreta":[{"k":"text","la":"Súscipe, clementíssime Deus, sacrifícium in honórem sancti Patriarchæ Jóachim, patris Maríæ Vírginis, majestáti tuæ oblátum: ut, ipso cum cónjuge sua et beatíssima prole intercedénte, perféctam cónsequi mereámur remissiónem peccatórum et glóriam sempitérnam."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut per hæc sacraménta, quæ súmpsimus, intercedéntibus méritis et précibus beáti Jóachim patris Genetrícis dilécti Fílii tui, Dómini nostri Jesu Christi, tuæ grátiæ in præsénti et ætérnæ glóriæ in futúro partícipes esse mereámur."},{"k":"macro","name":"Per eundem"}]},"hr":{"89ae4fff87d20bea":{"t":"<i>Pomolimo se</i>.\nBože, koji si htio da iznad svih svetih tvojih blaženi Joakim bude otac majke Sina tvoga, daj, molimo, da neprestano osjećamo zaštitu onoga kojega svetkovinu (spomen) slavimo.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"memoriam → ∅"},"975f592f0b5c43ee":{"t":"Primi, predobri Bože, žrtvu prikazanu tvome veličanstvu na čast svetoga patrijarhe Joakima. oca Djevice Marije, da po zagovoru njegovu, njegove žene i blažene kćeri zavrijedimo postići potpuno oproštenje grijeha i vječnu slavu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8724a95fd16a8f86":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da po ovim otajstvima što smo ih primili i po zaslugama i molitvama blaženog Joakima, oca Majke ljubljenog Sina tvoga Gospodina našeg Isusa Krista, zavrijedimo biti dionicima tvoje milosti u sadašnjosti i vječne slave u budućnosti.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"fa1d1cb65bfa5d86":{"t":"Ps 111, 9, Ps 111, 1\n(Ps 111, 9) Obilno je dijelio i davao siromasima, pravda njegova ostaje dovijeka, uzdići će se snaga i slava njegova. (Ps 111, 1) Blago čovjeku koji se boji Gospodina, koji se veoma raduje njegovim zapovijedima.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 111, 9) Obilno je dijelio i davao siromasima, pravda njegova ostaje dovijeka, uzdići će se snaga i slava njegova."},"d0743eab00685bfc":{"t":"Sir 31, 8-11\nČitanje knjige Mudrosti. Blago čovjeku koji se nađe bez ljage i ne teži za zlatom, niti se uzda u novac i blago. Tko je taj, da ga pohvalimo? U svojem je životu učinio divna djela. Tko je u tome prokušan i savršen bit će uvijek slavan. Mogao je sagriješiti, ali nije sagriješio, učiniti zlo, ali nije počinio. Zato priznaje njegova djela Gospodin, a njegovih će se milostinja sjećati sve skupine svetih."},"fb154f2dfc35a330":{"t":"Ps 111, 9 et 2\nObilno je dijelio i davao siromasima, pravda njegova ostaje dovijeka. Jako će bili na zemlji potomstvo njegovo, rod će pravednika biti blagoslovljen.\n\nPs 2, 7\n<i>Aleluja</i>, <i>aleluja</i>.\nO sveti Joakime, koji si bio Anin muž, a otac slavne Djevice, udijeli ovdje Božjim slugama pomoć spasenja. <i>Aleluja</i>."},"35136cb2edd6737a":{"t":"Mt 1, 1-16\nPočetak svetog Evanđelje po Mateju. Knjiga rođenja Isusa Krista, sina Davidova, sina Abrahamova. Abraham je imao sina Izaka, Izak je imao sina Jakova, Jakov je imao sina Judu i njegovu braću. Juda je imao sina Faresa i Zaru od Tamare, Fares je imao sina Ezrona, Ezron je imao sina Arama, Aram je imao sina Aminadaba, Aminadab je imao sina Nasona, Nason je imao sina Salmona, Salmon je imao sina Boza od Rahabe, Boz je Imao sina Obeda od Rute, Obed je imao sina Jeseja, Jesej je imao sina kralja Davida. Kralj David je imao sina Salamona s bivšom Urijinom ženom. Salamon je imao sina Roboama, Roboam je imao sina Abiju, Abija je imao sina Asu, Asa je imao sina Jozafata, Jozafat je imao sina Joatama, Joatam je imao sina Ahaza, Ahaz je imao sina Ezekiju, Ezekija je imao sina Manasiju, Manasija je imao sina Amona, Amon je imao sina Joziju, Jozija je imao sina Jehoniju i njegovu braću u vrijeme seobe u Babilon. A poslije seobe u Babilon Jehonija je imao sina Salatijela, Salatijel je imao sina Zorobabela, Zorobabel je imao sina Abijuda. Abijud je imao sina Elijacima, Elijacim je imao sina Azora, Azor je imao sina Sadoka, Sadok je imao sina Ahima, Ahim je imao sina Elijuda, Elijud je imao sina Eleazara, Eleazar je imao sina Matana, Matan je imao sina Jakova, Jakov je imao sina Josipa, muža Marijina, od koje se rodio Isus. koji se zove Krist."},"b389ff84b79a6464":{"t":"Ps 8, 6-7\nOkrunio si ga slavom i čašću i postavio si ga nad djela svojih ruku, Gospodine."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"43352d99b4b928c1":{"t":"Lk 12, 42\nEvo vjernog i razboritog sluge koga je postavio Gospodin nad svojom obitelji, da im na vrijeme daje za hranu pšenicu koja im pripada."}}});
